import kotlinx.coroutines.*
import kotlinx.coroutines.flow.*

// 模拟「用户输入搜索关键词」的事件流：持续产生数据
class SearchRepository {

    // 冷流：只有被 collect 时才会执行 flow 体
    fun queryFlow(): Flow<String> = flow {
        val keystrokes = listOf("kot", "kotl", "kotlin", "kotlin", "kotlin协程")
        for (q in keystrokes) {
            delay(150)                 // 模拟用户敲键盘的节奏
            emit(q)                    // 发射一个上游数据
        }
    }

    // 模拟网络请求：把关键词转成结果列表
    suspend fun requestApi(query: String): List<String> {
        delay(200)                     // 模拟网络延迟
        return listOf("$query-result1", "$query-result2")
    }

    // 把整条管道封装成一个可复用、可单测的函数
    fun searchResults(): Flow<SearchUiState> = queryFlow()
        .debounce(100)                 // 100ms 内没有新输入才放行，防抖
        .distinctUntilChanged()        // 过滤掉连续重复的关键词
        .map { it.trim().uppercase() } // 中间转换（纯函数，易测试）
        .flowOn(Dispatchers.Default)   // 以上游跑在 Default 调度器
        .map { query ->                // 发起 IO 请求
            try {
                SearchUiState.Success(requestApi(query))
            } catch (e: CancellationException) {
                throw e                // 协程取消必须原样抛出！
            } catch (e: Exception) {
                SearchUiState.Error(e.message ?: "unknown")
            }
        }
        .onStart { emit(SearchUiState.Loading) }  // 起始状态
        .catch { e -> emit(SearchUiState.Error(e.message ?: "flow error")) } // 只对上游生效
}

// UI 层只认识这三种状态，而不是异常
sealed interface SearchUiState {
    data object Loading : SearchUiState
    data class Success(val items: List<String>) : SearchUiState
    data class Error(val message: String) : SearchUiState
}

fun main() = runBlocking {
    val repo = SearchRepository()
    repo.searchResults().collect { state ->
        when (state) {
            is SearchUiState.Loading -> println("Loading...")
            is SearchUiState.Success -> println("结果: ${state.items}")
            is SearchUiState.Error -> println("错误: ${state.message}")
        }
    }
}

